// Alerte publiee par la carte cave (controleGeneral.publieAlerteRelance)
// {"Module","Relai","Evenement":"relance"|"defaut","Relance","MaxRelances","Message"}
const a = msg.payload || {};
let texte;
if (a.Evenement === 'defaut') {
    texte = '\u{1F6A8} *POMPE VIDE-CAVE EN DEFAUT*\n' + (a.Message || '') +
            '\n\nEnvoie /etat pour verifier, /acquitter une fois le probleme regle.';
} else if (a.Evenement === 'relance') {
    texte = '\u26A0\uFE0F Pompe vide-cave : relance ' + a.Relance + '/' + a.MaxRelances +
            '\n' + (a.Message || '');
} else {
    texte = '\u2139\uFE0F Pompe vide-cave : ' + JSON.stringify(a);
}
msg.payload = { chatId: env.get('CHAT_ID'), type: 'message', content: texte,
                options: { parse_mode: 'Markdown' } };
return msg;

// Refuse toute commande qui ne vient pas du chat autorise (en plus du filtre du bot)
const autorise = String(env.get('CHAT_ID'));
const chat = String((msg.originalMessage && msg.originalMessage.chat && msg.originalMessage.chat.id) || msg.payload.chatId);
if (chat !== autorise) {
    node.warn('Commande refusee depuis le chat ' + chat);
    return null;
}
flow.set('reponseAttendue', Date.now());
msg.topic = 'cmnd/' + env.get('TOPIC_CAVE') + '/EtatPompe';
msg.payload = '';
return msg;

// Refuse toute commande qui ne vient pas du chat autorise (en plus du filtre du bot)
const autorise = String(env.get('CHAT_ID'));
const chat = String((msg.originalMessage && msg.originalMessage.chat && msg.originalMessage.chat.id) || msg.payload.chatId);
if (chat !== autorise) {
    node.warn('Commande refusee depuis le chat ' + chat);
    return null;
}
flow.set('reponseAttendue', Date.now());
msg.topic = 'cmnd/' + env.get('TOPIC_CAVE') + '/AcquittePompe';
msg.payload = '';
return msg;

// Refuse toute commande qui ne vient pas du chat autorise (en plus du filtre du bot)
const autorise = String(env.get('CHAT_ID'));
const chat = String((msg.originalMessage && msg.originalMessage.chat && msg.originalMessage.chat.id) || msg.payload.chatId);
if (chat !== autorise) {
    node.warn('Commande refusee depuis le chat ' + chat);
    return null;
}
// '/pompe on' ou '/pompe off' (le noeud commande peut laisser ou retirer '/pompe')
const texte = String(msg.payload.content || '').replace(/^\/pompe(@\S+)?/i, '').trim().toUpperCase();
if (texte !== 'ON' && texte !== 'OFF') {
    return [null, { payload: { chatId: env.get('CHAT_ID'), type: 'message',
                               content: 'Usage : /pompe on  ou  /pompe off' } }];
}
flow.set('reponseAttendue', Date.now());
return [{ topic: 'cmnd/' + env.get('TOPIC_CAVE') + '/POWER1', payload: texte }, null];

// Reponses de la carte (stat/<topic>/RESULT). Transmises seulement si une commande
// Telegram vient d'etre envoyee (< 15 s) : sinon chaque changement de relais serait notifie.
const attente = flow.get('reponseAttendue') || 0;
if (Date.now() - attente > 15000) return null;

const r = msg.payload || {};
let texte = null;
const e = r.EtatPompe;
if (e) {
    const niveaux = Object.keys(e.Niveaux || {}).map(n => '  - ' + n + ' : ' + e.Niveaux[n]).join('\n');
    texte = (r.AcquittePompe ? '\u2705 Alerte acquittee\n\n' : '') +
            '*Pompe vide-cave* : ' + e.Pompe +
            (e.Pompe === 'ON' && e.ArretSecuriteDans ? ' (arret de securite dans ' + e.ArretSecuriteDans + ' s)' : '') +
            (e.Relance ? '\nRelance en cours : ' + e.Relance + '/' + e.MaxRelances : '') +
            '\nNiveaux :\n' + niveaux +
            '\nDerniere mise en route : ' + e.DerniereMiseEnRoute +
            '\nCycles du jour : ' + e.CyclesJour +
            (e.Alerte ? '\n\n\u{1F6A8} ' + e.Alerte : '');
} else if (r.POWER1) {
    texte = 'Pompe vide-cave : ' + r.POWER1 +
            (r.POWER1 === 'ON' ? ' (arret de securite automatique apres la minuterie)' : '');
}
if (!texte) return null;
flow.set('reponseAttendue', 0);
msg.payload = { chatId: env.get('CHAT_ID'), type: 'message', content: texte,
                options: { parse_mode: 'Markdown' } };
return msg;
